<template>
  <aside class="sidebar" :style="cardStyle">
    <h3 class="sidebar-title" :style="{ color: colors.blue }">
      <i class="pi pi-sliders-h" ></i> 
      Sections
    </h3>

    <nav>
      <TerminalButton
        v-for="tab in tabs"
        :key="tab.key"
        :style="navStyle(tab.key)"
        @click="$emit('change', tab.key)"
      >
        <IconChevron />
        {{ tab.label }}
      </TerminalButton>
    </nav>
  </aside>
</template>

<script setup>
import IconChevron from '@/components/atoms/IconChevron.vue'
import TerminalButton from '@/components/atoms/TerminalButton.vue'

const props = defineProps({
  tabs: {
    type: Array,
    required: true
  },
  active: {
    type: String,
    required: true
  },
  colors: {
    type: Object,
    required: true
  },
  cardStyle: {
    type: Object,
    required: true
  }
})

defineEmits(['change'])

const navStyle = (key) => ({
  backgroundColor: key === props.active ? props.colors.bg : 'transparent',
  border: `1px solid ${
    key === props.active ? props.colors.blue : 'transparent'
  }`,
  color: key === props.active ? props.colors.blue : '#a89984'
})
</script>

<style scoped>
.sidebar {
  padding: 1rem;
  border-radius: .5rem;
}

.sidebar-title {
  display: flex;
  gap: .5rem;
  margin-bottom: 1rem;
}
</style>
