    padding-left: 0;
    margin-top: -8px; /* Reduce el espacio entre el nombre y la descripción */
    font-size: 0.9em;
    white-space: pre-wrap; /* Mantiene el formato tree (saltos de línea y espacios) */
}

/* Ajuste para el formato tree/jerárquico */
.file-description > * {
    display: block; /* Asegura que cada línea del árbol ocupe su propio espacio */
